    public static function addOrUpdateUserByCom($info_com = array()){
        try {
            if(!empty($info_com['pkcom_id'])){
                $ucom_object = ActoAdministrativoPeer::getUserAddedInCom($info_com['pkcom_id'],$info_com['usuario_id'],$info_com['rol_id']);
                $esta_asignada = isset($info_com['esta_asignada']) ? $info_com['esta_asignada'] : 0;
                //**************************************************************************************************
                if(is_array($ucom_object)){
                    foreach ($ucom_object as $uobject) {
                        if($uobject->getEstadoactoadministrativoId() != $info_com['estadocom_id']){
                            $uobject->setEstadoactoadministrativoId($info_com['estadocom_id']);
                            $uobject->setFechaAsigna(($esta_asignada ? date("Y-m-d G:i:s") : null));
                            $uobject->setEstaAsignada($esta_asignada);
                            $uobject->setActoadminetapaId(isset($info_com['actoadminetapa_id']) ? $info_com['actoadminetapa_id'] : $uobject->getActoadminetapaId());
                            $uobject->save();
                        }
                    }
                }elseif($ucom_object == null){
                    $ucom_object = ActoAdministrativoPeer::addUserByActo($info_com);
                }elseif($ucom_object->getEstadoactoadministrativoId() != $info_com['estadocom_id']){
                    $ucom_object->setEstadoactoadministrativoId($info_com['estadocom_id']);
                    $ucom_object->setFechaAsigna(($esta_asignada ? date("Y-m-d G:i:s") : null));
                    $ucom_object->setEstaAsignada($esta_asignada);
                    $ucom_object->setActoadminetapaId(isset($info_com['actoadminetapa_id']) ? $info_com['actoadminetapa_id'] : $ucom_object->getActoadminetapaId());
                    $ucom_object->save();
                }
                //**************************************************************************************************
                return $ucom_object;
            }
        } catch (PropelException $th) {
            return null;
        } catch (Exception $th) {
            return null;
        }
    }

