    public static function getHashComData(ActoAdministrativo $object)
	{
        $dstorage = array();
		$object_class = ActoAdministrativoPeer::OM_CLASS;
		$field_include = array( 'ActoadministrativoId', 'Asunto', 'PeriodoId', 'NumeroResolucion', 'FechaCreacion', 'SubserieId', 'RegionalId', 'DependenciaId');
		try
        {
			$peer_class = sprintf("%sPeer",$object_class);
            $campos_objeto = $peer_class::getFieldNames();
            foreach($campos_objeto as $field)
            {
				if(in_array($field,$field_include))
                {
					$instanceMethod = 'get'.$field;
					$dstorage[] = $object->$instanceMethod();
				} 
            }            
        }
        catch(PropelException $px)
        { 
            return false;
        }
        catch(Throwable $th)
        { 
            return false;
        }
        catch(Exception $ex)
        { 
            return false;
        } 
        //********************************************************************
        $str_encrypt = implode("",$dstorage);
        $hashLog = hash('sha256', $str_encrypt);
        
        return $hashLog;
    }

