            $tobject->setEstaentregado(isset($params['esta_entregado']) ? $params['esta_entregado'] : 0);
            $tobject->setSuborigen(isset($params['id_suborigen']) ? trim($params['id_suborigen']) : null);
            $tobject->setMarcoNormativo(isset($params['marco_normativo']) ? trim($params['marco_normativo']) : null);
            if (!empty($params['numero_resolucion'])) {
                $tobject->setNumeroResolucion(trim($params['numero_resolucion']));
            }
            //$tobject->setTipoEnvio(isset($params['tipo_envio']) ? $params['tipo_envio'] : null);
            //$tobject->setTipoMasivo(isset($params['tipo_masivo']) ? (!empty($params['tipo_masivo']) ? 1 : 0) : 0);
            $tobject->save();
            //*****************************************************************************************************           
            return $tobject;
        }catch(PropelException $ex){
            return null;
        }catch(\Exception $ex){
			return null;
        }catch(\Throwable $ex){
			return null;
        }
    }

    /**
     * ActoAdministrativoPeer::isExistActoByNumResolucion()
     * Valida que el numero de resolucion informado en la plantilla de radicacion masiva
     * no exista ya para la misma subserie (evita radicar dos veces el mismo acto externo).
     * @return bool
     */
    public static function isExistActoByNumResolucion($numero_resolucion, $subserie_id)
    {
        try {
            if (empty($numero_resolucion) || empty($subserie_id)) {
                return false;
            }
            $c = new Criteria();
            $c->add(ActoAdministrativoPeer::NUMERO_RESOLUCION, trim($numero_resolucion));
            $c->add(ActoAdministrativoPeer::SUBSERIE_ID, $subserie_id);
            return ActoAdministrativoPeer::doCount($c) > 0;
        } catch (PropelException $ex) {
            return false;
        } catch (\Throwable $ex) {
            return false;
        }
    }

    public static function getDigitFormatFileExist($filepath,$filename)
    {
        $extensions = explode(";",ParametroPeer::retrieveByPk(31)->getValortexto());
        $digitDocumentFile = "";
        try{
            foreach($extensions as $format){
                $digitDocumentFile = $filepath. DIRECTORY_SEPARATOR .$filename.'.'.$format;
                if(file_exists($digitDocumentFile)){
                    return $digitDocumentFile;
                }
            }
        }catch(PropelException $ex){
            return $digitDocumentFile;
        }catch(\Exception $ex){
            return $digitDocumentFile;
        }catch(\Throwable $ex){
            return $digitDocumentFile;
        }
    }

    public static function initFolderDigit($regional_id,$periodo,$useTmp = false)
    {
        $dirRaiz    = ParametroPeer::retrieveByPk(75)->getValortexto();
        $dir_alias  = ParametroPeer::retrieveByPk(76)->getValortexto();
        $dirTmp     = $useTmp ? ParametroPeer::retrieveByPk(65)->getValortexto() : "";
        //************************************************************************************
        $regional = RegionalPeer::retrieveByPK($regional_id);
        //************************************************************************************
        $entidad_folder = trim($regional->getEntidad()->getDirectorioName());
        $regional_folder = trim($regional->getDirectorioName());
        $entidad_text = $entidad_folder ? $entidad_folder : "";
        $entidad_text = $entidad_text ? ($regional_folder ? $entidad_folder.DIRECTORY_SEPARATOR.$regional_folder : $entidad_folder) : "";
        //************************************************************************************
        $directorio_digit = simad_util::NormalizePath($dirRaiz.$entidad_text.DIRECTORY_SEPARATOR.$dir_alias.DIRECTORY_SEPARATOR.$periodo);
        $folder_attach = simad_util::createPath($directorio_digit);        
        $basic_path = $entidad_text.DIRECTORY_SEPARATOR.$dir_alias.DIRECTORY_SEPARATOR.$periodo;
        //************************************************************************************        
        $array_url['basic_path'] = $basic_path;
        $array_url['full_path'] = $folder_attach;
        $array_url['temp_path'] = $dirTmp;
        $array_url['alias_web'] = "";
        //************************************************************************************
        return $array_url;
    }

    public static function deleteCascada($actoadministrativo_id)
    {
        try {
            if (empty($actoadministrativo_id) || !is_numeric($actoadministrativo_id)) {
                return false;
            }
            $conexion = Propel::getConnection();
            //****************************************************************************************************
            $query01 = "DELETE FROM %s WHERE %s = " . $actoadministrativo_id;
            $sql01      = sprintf($query01, ActoadministrativoUsuarioPeer::TABLE_NAME, ActoadministrativoUsuarioPeer::ACTOADMINISTRATIVO_ID);
            $sentencia = $conexion->prepare($sql01);
            $sentencia->execute();
            //****************************************************************************************************
            $query03 = "DELETE FROM %s WHERE %s = " . $actoadministrativo_id;
            $sql03      = sprintf($query03, ActoadministraInteresadoPeer::TABLE_NAME, ActoadministraInteresadoPeer::ACTOADMINISTRATIVO_ID);
            $sentencia = $conexion->prepare($sql03);
            $sentencia->execute();
            //****************************************************************************************************
            $query02 = "DELETE FROM %s WHERE %s = " . $actoadministrativo_id;
            $sql02      = sprintf($query02, ActoAdministrativoPeer::TABLE_NAME, ActoAdministrativoPeer::ACTOADMINISTRATIVO_ID);
            $sentencia = $conexion->prepare($sql02);
            $sentencia->execute();
        } catch (PropelException $th) {
            return false;
        } catch (\Exception $th) {
            return false;
        }
    }
